sys_script_include.script:
var FoodBaseProblemMatcherUtil = Class.create();

FoodBaseProblemMatcherUtil.prototype = {

    initialize: function() {},

    // Main function — call this with a Food Complaint sys_id
    matchOrCreate: function(complaintSysId) {

        var complaint = new GlideRecord('x_snc_campus_foo_1_food_complaint');

        if (!complaint.get(complaintSysId)) {
            gs.error('FoodBaseProblemMatcherUtil: Complaint not found ' + complaintSysId);
            return;
        }

        var baseProblem = this._findExisting(complaint);

        if (baseProblem) {
            this._updateExisting(complaint, baseProblem);
        } else {
            this._createNew(complaint);
        }
    },

    // Find Base Problem using Use Case + Problem Type (Normalized) + Mess Hall
    // Excludes Resolved and Closed — a fixed problem should not silently reopen
    _findExisting: function(complaint) {

    var bp = new GlideRecord('x_snc_campus_foo_1_food_base_problem');

    bp.addQuery('use_case', complaint.use_case);
    bp.addQuery('problem_type_normalized', complaint.problem_type_normalized);
    bp.addQuery('mess_hall', complaint.mess_hall);
    bp.addQuery('status', '!=', 'closed');
    bp.query();

    if (bp.next()) {
        return bp;
    }

    return null;
},

    // Existing Base Problem found — link and update counts
    _updateExisting: function(complaint, bp) {

        complaint.base_problem = bp.getUniqueValue();
        complaint.update();

        bp.ticket_count = parseInt(bp.ticket_count || 0, 10) + 1;
        bp.open_ticket_count = parseInt(bp.open_ticket_count || 0, 10) + 1;
        bp.latest_ticket = complaint.getUniqueValue();
        bp.latest_reported_at = complaint.opened_at;
        bp.student_count = this._countDistinctStudents(bp.getUniqueValue());

        bp.update();

        gs.info('Food Complaint ' + complaint.number + ' linked to existing Base Problem ' + bp.number);
    },

    // No Base Problem found — create a new one
    _createNew: function(complaint) {

        var bp = new GlideRecord('x_snc_campus_foo_1_food_base_problem');
        bp.initialize();

        bp.use_case = complaint.use_case;
        bp.mess_hall = complaint.mess_hall;
        bp.meal_type = complaint.meal_type;
        bp.problem_type = complaint.problem_type;
        bp.problem_type_normalized = complaint.problem_type_normalized;

        bp.first_ticket = complaint.getUniqueValue();
        bp.latest_ticket = complaint.getUniqueValue();
        bp.first_reported_at = complaint.opened_at;
        bp.latest_reported_at = complaint.opened_at;

        bp.student_count = 1;
        bp.ticket_count = 1;
        bp.open_ticket_count = 1;
        bp.resolved_ticket_count = 0;
        bp.status = 'active';

        var bpSysId = bp.insert();

        complaint.base_problem = bpSysId;
        complaint.update();

        gs.info('Food Complaint ' + complaint.number + ' created new Base Problem ' + bp.number);
    },

    // Real distinct student count, not a naive increment
    _countDistinctStudents: function(baseProblemSysId) {
        var ga = new GlideAggregate('x_snc_campus_foo_1_food_complaint');
        ga.addQuery('base_problem', baseProblemSysId);
        ga.groupBy('student');
        ga.query();

        var count = 0;
        while (ga.next()) {
            count++;
        }
        return count;
    },

    type: 'FoodBaseProblemMatcherUtil'
};
